c037.try_sql:
-- manager_id contains a NULL (King): NOT IN returns nothing, NOT EXISTS works
SELECT e.last_name FROM employees e
WHERE e.employee_id NOT IN (SELECT m.manager_id FROM employees m);
SELECT e.last_name FROM employees e
WHERE NOT EXISTS (SELECT 1 FROM employees m WHERE m.manager_id = e.employee_id);

c039.try_sql:
-- > ALL gives the same as > MAX: compare both results
SELECT e.last_name, e.salary FROM employees e
WHERE e.salary > ALL (SELECT salary FROM employees WHERE department_id = 20);
SELECT e.last_name, e.salary FROM employees e
WHERE e.salary > (SELECT MAX(salary) FROM employees WHERE department_id = 20);

c040.try_sql:
-- Department 40 has no employees: NULL. Department 30 has four: ORA-01427
SELECT (SELECT last_name FROM employees WHERE department_id = 40) AS zero_wierszy FROM dual;
SELECT (SELECT last_name FROM employees WHERE department_id = 30) AS wiele_wierszy FROM dual;

c400.try_sql:
-- Umbrella (4) has no orders: without WHERE EXISTS it is changed too (NULL)
UPDATE customers c
SET c.credit_limit = (SELECT MAX(o.order_id) FROM orders o WHERE o.customer_id = c.customer_id);
SELECT customer_id, customer_name, credit_limit FROM customers ORDER BY customer_id;

c401.try_sql:
-- If the subquery saw the changes, the salaries would keep growing. Everyone gets 24001
UPDATE employees e SET e.salary = (SELECT MAX(e2.salary) + 1 FROM employees e2);
SELECT DISTINCT salary FROM employees;

c402.try_sql:
-- Two columns from one correlated subquery (parentheses around the list!)
UPDATE employees e
SET (e.salary, e.commission_pct) = (SELECT MAX(e2.salary), MAX(e2.commission_pct)
                                    FROM employees e2 WHERE e2.department_id = e.department_id)
WHERE e.department_id = 20;
SELECT last_name, salary, commission_pct FROM employees WHERE department_id = 20;

c403.try_sql:
-- Delete the customers without orders (only Umbrella is deleted)
DELETE FROM customers c
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id);
SELECT customer_id, customer_name FROM customers ORDER BY customer_id;

