c405.try_sql:
-- IN and = ANY work with many rows, a plain = does not (ORA-01427)
SELECT last_name, salary FROM employees
WHERE salary = ANY (SELECT salary FROM employees WHERE job_title = 'Programmer');
SELECT last_name, salary FROM employees
WHERE salary = (SELECT salary FROM employees WHERE job_title = 'Programmer');

c1402.try_sql:
-- The expression SUM(quantity) has no alias, so there is no column v.total
SELECT v.order_id, v.total
FROM (SELECT order_id, SUM(quantity) FROM order_items GROUP BY order_id) v;

c1403.try_sql:
-- DISTINCT leaves 9000, 6000, 4800: still three rows
SELECT last_name FROM employees
WHERE salary = (SELECT DISTINCT salary FROM employees WHERE job_title = 'Programmer');

c1405.try_sql:
-- <> ANY (20, 30): everyone with a department (8). NOT IN (20, 30): only King
SELECT COUNT(*) FROM employees WHERE department_id <> ANY (20, 30);
SELECT last_name FROM employees WHERE department_id NOT IN (20, 30);

c1407.try_sql:
-- Pairs (6000, 30) and (4800, 20): pairwise 2 rows, separately 4 (Russell and Lorentz "crosswise")
SELECT last_name, salary, department_id FROM employees
WHERE (salary, department_id) IN (SELECT salary, department_id FROM employees WHERE employee_id IN (104, 106));
SELECT last_name, salary, department_id FROM employees
WHERE salary IN (SELECT salary FROM employees WHERE employee_id IN (104, 106))
  AND department_id IN (SELECT department_id FROM employees WHERE employee_id IN (104, 106));

c1408.try_sql:
-- No correlation: EXISTS is always true, so all 4 departments come back
SELECT d.department_name FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.salary > 20000);
SELECT d.department_name FROM departments d
WHERE EXISTS (SELECT 1 FROM employees e WHERE e.salary > 20000
              AND e.department_id = d.department_id);

c1410.try_sql:
-- Product 15 exists but has list_price NULL: line 1004/2 gets NULL
UPDATE order_items oi
SET oi.unit_price = (SELECT p.list_price FROM products p WHERE p.product_id = oi.product_id)
WHERE EXISTS (SELECT 1 FROM products p WHERE p.product_id = oi.product_id);
SELECT order_id, line_no, product_id, unit_price FROM order_items WHERE unit_price IS NULL;

c1411.try_sql:
-- Umbrella and Hooli have no NEW orders, but Hooli has another order: ORA-02292, nothing disappears
DELETE FROM customers c
WHERE NOT EXISTS (SELECT 1 FROM orders o
                  WHERE o.customer_id = c.customer_id AND o.status = 'NEW');
SELECT COUNT(*) FROM customers;
